735→export async function handleFilesRemove(body: unknown, auth: V2AuthContext, requestId: string, deps: SkillRouterDeps): Promise<ApiResponseEnvelope> {
736→  const t0 = Date.now();
737→  const pre = await precheckWrite(filesRemoveRequestSchema, body, auth, deps, requestId);
738→  if (!pre.ok) { obsLogger.warn("skill.handleFilesRemove.done", { req_id: requestId, code: pre.envelope.code, dur_ms: Date.now() - t0, reason: "precheck" }); return pre.envelope; }
739→
740→  if (deps.quotaManager) {
741→    const check = await deps.quotaManager.checkMemoryQuota(auth.serviceId, 1);
742→    if (!check.allowed) {
743→      obsLogger.warn("skill.handleFilesRemove.done", { req_id: requestId, code: 4291, dur_ms: Date.now() - t0, reason: "quota", current: check.current, limit: check.limit });
744→      return errorEnvelope(4291, `Memory limit exceeded (current=${check.current}, limit=${check.limit})`, requestId);
745→    }
746→  }
747→
748→  try {
749→    const r = await pre.core.removeFiles(pre.data);
750→    obsLogger.info("skill.handleFilesRemove.done", { req_id: requestId, code: 0, dur_ms: Date.now() - t0, skill_id: r.skill_id, version: r.version, paths: pre.data.paths.length });
751→    return successEnvelope(toSummary(r), requestId);
752→  } catch (e) {
753→    obsLogger.error("skill.handleFilesRemove.done", { req_id: requestId, dur_ms: Date.now() - t0, skill_id: pre.data.skill_id, expected_version: pre.data.expected_version }, e instanceof Error ? e : undefined);
754→    return mapCoreError(e, requestId, deps, { skill_id: pre.data.skill_id, expected_version: pre.data.expected_version });
755→  }
756→}
