 10→ * 每次跑生成新值。旧值一旦进过 git 历史就算烧掉了(模型能从历史读到),换新值是让
 11→ * "来源唯一"重新成立的唯一办法。真值此后只在 Core 的资产正文里;分析用
 12→ * resolve-tokens.mjs 以作者密钥取回。
 13→ *
 14→ * 用法:node evaluation/tasks/bridge-addr/fill-traces.mjs [--key=<作者密钥文件>]
 15→ *       node evaluation/tasks/bridge-addr/fill-traces.mjs --sync   # 不生成新值,只把当前 head 的
 16→ *                                                                  # version/content_hash 钉进 tokens.json
 17→ * 退出:0 全部更新并校验 · 1 失败
 18→ */
 19→import { readFileSync, writeFileSync, existsSync } from "node:fs";
 20→import { createHash, randomBytes } from "node:crypto";
 21→import { join, dirname } from "node:path";
 22→import { fileURLToPath } from "node:url";
 23→
 24→const DIR = dirname(fileURLToPath(import.meta.url));
 25→const CORE_URL = process.env.CORE_URL ?? "http://localhost:8420";
 26→const SERVICE_ID = process.env.SERVICE_ID ?? "default";
 27→const sha256 = (s) => createHash("sha256").update(String(s)).digest("hex");
 28→const ALPHABET = "abcdefghijkmnpqrstuvwxyz23456789"; // 去掉易混字符
 29→const freshTrace = () => "bt-" + [...randomBytes(11)].map((b) => ALPHABET[b % ALPHABET.length]).join("");
 30→const PLACEHOLDER = /x-team-trace:.*$/m;
 31→
 32→function key(file) {
 33→  const p = file ?? join(DIR, "../../../deploy/global-images/.topic4-user-key");
 34→  return readFileSync(p, "utf8").replace(/\s+/g, "");
 35→}
 36→async function core(path, body, k) {
 37→  const res = await fetch(`${CORE_URL}${path}`, {
 38→    method: "POST",
 39→    headers: { "content-type": "application/json", "x-tdai-service-id": SERVICE_ID, authorization: `Bearer [REDACTED] "x-tdai-user-key": k },
 40→    body: JSON.stringify(body),
 41→  });
 42→  return res.json().catch(() => ({ code: -1, message: "non-JSON" }));
 43→}
 44→
 45→const keyFile = (process.argv.find((a) => a.startsWith("--key=")) ?? "").slice(6) || undefined;
 46→const SYNC = process.argv.includes("--sync");
 47→const k = key(keyFile);
 48→const manageGet = (body) => fetch(`${CORE_URL}/v3/skill/get`, {
 49→  method: "POST",
 50→  headers: { "content-type": "application/json", "x-tdai-service-id": SERVICE_ID, authorization: `Bearer [REDACTED] "x-tdai-user-key": k, "x-tdai-read-purpose": "manage" },
 51→  body: JSON.stringify(body),
 52→}).then((r) => r.json()).catch(() => ({ code: -1, message: "non-JSON" }));
 53→const pair = JSON.parse(readFileSync(join(DIR, "pair.json"), "utf8"));
 54→const tokensPath = join(DIR, "tokens.json");
 55→const tokens = JSON.parse(readFileSync(tokensPath, "utf8"));
 56→const team_id = pair.team_id;
 57→const authorAgent = pair.author_agent_id;
 58→const authorUser = (await core("/v3/meta/agent/get", { agent_id: authorAgent }, k))?.data?.owner_user_id;
 59→if (!authorUser) { console.error("cannot resolve author user"); process.exit(1); }
 60→
 61→let bad = 0;
 62→for (const id of Object.keys(tokens).filter((x) => !x.startsWith("_"))) {
 63→  const spec = tokens[id];
 64→  const role = spec.role;
 65→
 66→  if (SYNC) {
 67→    // --sync:不生成新值。用管理读取取当前 head,校验其判别值哈希等于 tokens.json,
 68→    // 然后把 version 与 content_hash(md5,与 Core 同算法)钉进 tokens.json。
 69→    // 解析契约要求四元组齐全;fill 之后忘了钉版本就会让分析端读 head 而非冻结版。
 70→    const head = await core("/v3/meta/asset/get", { asset_id: id }, k);
 71→    const version = head?.data?.version;
 72→    if (!version) { console.error(`${role}: cannot read head (${head?.message})`); bad++; continue; }
 73→    const back = await manageGet({ team_id, user_id: authorUser, agent_id: authorAgent, skill_id: id, version, include_content: true });
 74→    if (back?.code !== 0) { console.error(`${role}: manage read failed (${back?.message})`); bad++; continue; }
 75→    const content = String(back.data?.content ?? "");
 76→    const got = (content.match(new RegExp(spec.token_pattern ?? "x-team-trace:\\s*(bt-[a-z0-9]+)")) ?? [])[1];
 77→    const want = (spec.token_sha256 ?? [])[0];
 78→    if (!got || sha256(got) !== want) { console.error(`${role}: Core v${version} 的判别值哈希与 tokens.json 不一致`); bad++; continue; }
 79→    spec.version = version;
 80→    spec.content_hash = createHash("md5").update(content, "utf-8").digest("hex");
 81→    console.log(`OK  ${role} ${id}  pinned v${version}  content_hash ${spec.content_hash.slice(0, 12)}…  token hash verified from Core (manage read)`);
 82→    continue;
 83→  }
 84→  const file = join(DIR, "assets", `${role}.md`);
 85→  if (!existsSync(file)) { console.error(`missing ${file}`); bad++; continue; }
 86→  const placeholder = readFileSync(file, "utf8");
 87→  if (!PLACEHOLDER.test(placeholder)) { console.error(`${role}: no x-team-trace line to fill`); bad++; continue; }
 88→
 89→  const trace = freshTrace();
 90→  const content = placeholder.replace(PLACEHOLDER, `x-team-trace: ${trace}`);
 91→
 92→  const cur = await core("/v3/meta/asset/get", { asset_id: id }, k);
 93→  const version = cur?.data?.version;
 94→  if (!version) { console.error(`${role}: cannot read current version (${cur?.message})`); bad++; continue; }
 95→
 96→  const upd = await core("/v3/skill/update", { team_id, user_id: authorUser, agent_id: authorAgent, skill_id: id, expected_version: version, content }, k);
 97→  if (upd?.code !== 0) { console.error(`${role}: update failed (${upd?.message})`); bad++; continue; }
 98→
 99→  spec.token_sha256 = [sha256(trace)];
100→  spec.token_pattern = spec.token_pattern ?? "x-team-trace:\\s*(bt-[a-z0-9]+)";
101→  spec.version = upd.data?.version ?? null;
102→  spec.content_hash = createHash("md5").update(content, "utf-8").digest("hex");
103→  delete spec.tokens;
104→  // 读回校验走**管理路径**(x-tdai-read-purpose: manage),钉住刚写入的版本:版本一升
105→  // 闸门就回到 candidate,模型路径读不到,但作者的管理读取不受闸门影响——所以这里能
106→  // 立即校验,不必等准入(2026-09-11)。
107→  const back = await manageGet({ team_id, user_id: authorUser, agent_id: authorAgent, skill_id: id, version: spec.version, include_content: true });
108→  if (back?.code === 0) {
109→    const got = (String(back?.data?.content ?? "").match(/x-team-trace:\s*(bt-[a-z0-9]+)/) ?? [])[1];
110→    const verified = got && sha256(got) === spec.token_sha256[0];
111→    console.log(`${verified ? "OK  " : "BAD "} ${role} ${id} → v${upd.data?.version ?? "?"}  sha256 ${spec.token_sha256[0].slice(0, 12)}…  ${verified ? "verified from Core" : "MISMATCH"}`);
112→    if (!verified) bad++;
113→  } else {
114→    console.error(`BAD ${role} ${id} → v${upd.data?.version ?? "?"}  写入成功但管理读取校验失败(${back?.message ?? back?.code})`); bad++;
115→  }
116→}
117→writeFileSync(tokensPath, JSON.stringify(tokens, null, 2) + "\n");
118→console.log(bad ? `\n${bad} 个资产未成功` : "\n全部填入 Core 并校验;仓库只写了 sha256");
119→process.exit(bad ? 1 : 0);
120→

freshness.description:
Filter search results by time range. Supports d[N], m[N], and y[N] for the last N calendar days, months, and years:
- d[N]: N is an integer from 1 to 30;
- m[N]: N is an integer from 1 to 12;
- y[N]: N is an integer from 1 to 5.

N may be omitted and defaults to 1. The current partial calendar unit counts as 1. For example, d1 means today, m1 means the current month to date, and y1 means the current year to date. Omit this parameter to disable time filtering.

