export async function fetchResource({ skillId, path, bridgeBase, fetcher = globalThis.fetch }) {
  if (typeof fetcher !== "function") {
    throw new Error("fetchResource needs a fetcher (or globalThis.fetch)");
  }
  const url = `${String(bridgeBase).replace(/\/+$/, "")}/files/read`;
  const res = await fetcher(url, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ skill_id: skillId, path, encoding: "base64" }),
  });

  // A real Response exposes json(); tests may hand back the envelope directly.
  const envelope = typeof res?.json === "function" ? await res.json() : res;
  if (!envelope || envelope.code !== 0) {
    throw new Error(envelope?.message ?? "skill resource read failed");
  }

  const data = envelope.data ?? {};
  const content = data.content ?? "";
  return data.encoding === "utf-8" ? Buffer.from(content, "utf-8") : Buffer.from(content, "base64");
}
"}

