import assert from "node:assert/strict";
import { fetchResource } from "./fetch-resource.mjs";

const BASE = "http://127.0.0.1:8096/skill-bridge/v3/skill";
const b64 = (s) => Buffer.from(s, "utf-8").toString("base64");

/** A stub fetcher that records how it was called and answers with `envelope`. */
function stubOf(envelope) {
  const calls = [];
  const fetcher = async (url, init) => {
    calls.push({ url, init });
    return { json: async () => envelope };
  };
  return { fetcher, calls };
}

test("returns the resource's raw bytes, asking the bridge for base64", async () => {
  const raw = Buffer.from([0x00, 0xff, 0x10, 0x80]);
  const { fetcher, calls } = stubOf({ code: 0, message: "ok", data: { content: raw.toString("base64"), encoding: "base64" } });

  const out = await fetchResource({ skillId: "skl-abc", path: "scripts/run.sh", bridgeBase: BASE, fetcher });

  assert.ok(Buffer.isBuffer(out));
  assert.deepEqual(out, raw);
  assert.equal(calls.length, 1);
  assert.equal(calls[0].url, `${BASE}/files/read`);
  assert.equal(calls[0].init.method, "POST");
  assert.deepEqual(JSON.parse(calls[0].init.body), { skill_id: "skl-abc", path: "scripts/run.sh", encoding: "base64" });
});

test("a trailing slash on the bridge base does not double up", async () => {
  const { fetcher, calls } = stubOf({ code: 0, data: { content: b64("x"), encoding: "base64" } });
  await fetchResource({ skillId: "skl-abc", path: "a", bridgeBase: `${BASE}/`, fetcher });
  assert.equal(calls[0].url, `${BASE}/files/read`);
});

test("an empty resource is a zero-byte Buffer, not an error", async () => {
  const { fetcher } = stubOf({ code: 0, message: "ok", data: { content: "", encoding: "base64" } });
  const out = await fetchResource({ skillId: "skl-abc", path: "empty.txt", bridgeBase: BASE, fetcher });
  assert.ok(Buffer.isBuffer(out));
  assert.equal(out.length, 0);
});

test("a utf-8 resource is decoded as text, not base64", async () => {
  const { fetcher } = stubOf({ code: 0, data: { content: "héllo", encoding: "utf-8" } });
  const out = await fetchResource({ skillId: "skl-abc", path: "README.md", bridgeBase: BASE, fetcher });
  assert.deepEqual(out, Buffer.from("héllo", "utf-8"));
});

test("an error envelope is thrown with the envelope's message", async () => {
  const { fetcher } = stubOf({ code: 40401, message: "SKILL_NOT_FOUND: no such resource" });
  await assert.rejects(
    () => fetchResource({ skillId: "skl-abc", path: "SKILL.md", bridgeBase: BASE, fetcher }),
    /SKILL_NOT_FOUND: no such resource/,
  );
});

test("fetcher defaults to globalThis.fetch", async () => {
  const original = globalThis.fetch;
  const calls = [];
  globalThis.fetch = async (url, init) => {
    calls.push({ url, init });
    return { json: async () => ({ code: 0, data: { content: b64("ok"), encoding: "base64" } }) };
  };
  try {
    const out = await fetchResource({ skillId: "skl-abc", path: "a.txt", bridgeBase: BASE });
    assert.deepEqual(out, Buffer.from("ok", "utf-8"));
    assert.equal(calls[0].url, `${BASE}/files/read`);
  } finally {
    globalThis.fetch = original;
  }
});
"}

freshness.description:
Filter search results by time range. Supports d[N], m[N], and y[N] for the last N calendar days, months, and years:
- d[N]: N is an integer from 1 to 30;
- m[N]: N is an integer from 1 to 12;
- y[N]: N is an integer from 1 to 5.

N may be omitted and defaults to 1. The current partial calendar unit counts as 1. For example, d1 means today, m1 means the current month to date, and y1 means the current year to date. Omit this parameter to disable time filtering.

